private lemma exists_cover_approximation (c_pos : 0 < c) (h : TotallyBounded (Set.univ : Set (EmpiricalFunctionSpace F S)))
  (fh : ι) (j : ℕ) :
  ∃ f_j : EmpiricalFunctionSpace F S, f_j ∈ cj c_pos h j ∧ empiricalDist S (F fh) f_j ≤ ej c j

private lemma coverApprox_mem_cover (c_pos : 0 < c)
    (h : TotallyBounded (Set.univ : Set (EmpiricalFunctionSpace F S)))
    (fh : ι) (j : ℕ) : coverApprox c_pos h fh j ∈ cj c_pos h j

private lemma empiricalDist_coverApprox_le_radius (c_pos : 0 < c)
    (h : TotallyBounded (Set.univ : Set (EmpiricalFunctionSpace F S)))
    (fh : ι) (j : ℕ) : empiricalDist S (F fh) (coverApprox c_pos h fh j) ≤ ej c j

private lemma chain_decomposition (c_pos : 0 < c) (h : TotallyBounded (Set.univ : Set (EmpiricalFunctionSpace F S)))
  (fh : ι) (n : ℕ):
      F fh = F fh - chainApprox c_pos h fh n + ∑ j : Fin n, (chainApprox c_pos h fh ((j : ℕ) + 1) - chainApprox c_pos h fh ((j : ℕ)))

private lemma empiricalDist_to_chainApprox_le_ej (c_pos : 0 < c) (h : TotallyBounded (Set.univ : Set (EmpiricalFunctionSpace F S))) (fh : ι) (n : ℕ)
  (cs : ∀ f : ι, empiricalNorm S (F f) ≤ c) :
  empiricalDist S (F fh) (chainApprox c_pos h fh n) ≤ c / 2 ^ n

private lemma partA_sup_bound (c_pos : 0 < c) (h : TotallyBounded (Set.univ : Set (EmpiricalFunctionSpace F S)))
  (cs : ∀ f : ι, empiricalNorm S (F f) ≤ c) (n : ℕ) : ∀ (σ : Signs m) (fh : ι),
  ((∑ i : Fin m, (σ i : ℝ) * ((F fh) (S i) - chainApprox c_pos h fh n (S i))) ≤ (m : ℝ) * (ej c n))

private lemma chainApprox_increment_signed_sum_bound (c_pos : 0 < c) (h' : TotallyBounded (Set.univ : Set (EmpiricalFunctionSpace F S))) (j : ℕ)
  (σ : Signs m) (fh : ι) (cs : ∀ f : ι, empiricalNorm S (F f) ≤ c) :
  ∑ i : Fin m, (σ i : ℝ) * (chainApprox c_pos h' fh (j + 1) - chainApprox c_pos h' fh j) (S i) ≤ m * (c / 2 ^ (j+1) + c / 2 ^ j)

private lemma combine_partA_partB (c_pos : 0 < c) (h' : TotallyBounded (Set.univ : Set (EmpiricalFunctionSpace F S))) (n : ℕ) (m_pos : 0 < m)
  (cs : ∀ f : ι, empiricalNorm S (F f) ≤ c) :
  empiricalRademacherComplexity_without_abs m F S ≤ (ej c n) + 12 / (Real.sqrt m)*(∑ j : Fin n, ((ej c (j+1) - ej c (j+2))*√(Real.log (coveringNumberNat h' (ej c (j+1))))))

private lemma entropy_sum_to_integral_bound (c_pos : 0 < c) (h' : TotallyBounded (Set.univ : Set (EmpiricalFunctionSpace F S))) (n : ℕ) (m_pos : 0 < m)
  (cs : ∀ f : ι, empiricalNorm S (F f) ≤ c) :
  empiricalRademacherComplexity_without_abs m F S ≤ 2 * (ej c (n+1)) + 12 / (Real.sqrt m)*(∫ (x : ℝ) in (ej c (n+1))..(c/2),√(Real.log (coveringNumberNat h' x)))

proof:
:= by
  let standard : Fintype (Fin n → ({-1, 1} : Finset ℤ)) :=
    @Pi.instFintype (Fin n) (fun _ ↦ ({-1, 1} : Finset ℤ))
      (inferInstanceAs (DecidableEq (Fin n))) (inferInstanceAs (Fintype (Fin n)))
      (fun _ ↦ inferInstanceAs (Fintype ({-1, 1} : Finset ℤ)))
  calc
    Fintype.card (Signs n) =
        @Fintype.card (Fin n → ({-1, 1} : Finset ℤ)) standard :=
      @Fintype.card_congr (Signs n) (Fin n → ({-1, 1} : Finset ℤ))
        instFintypeSigns standard (Equiv.refl _)
    _ = 2 ^ n := by
      rw [Fintype.card_fun, Fintype.card_coe, Fintype.card_fin]
      congr 1

