    {θ_star : EuclideanSpace ℝ (Fin d)} (x : Fin n → EuclideanSpace ℝ (Fin d)) :
    Bornology.IsBounded (l1EmpiricalImage x '' (l1LocalizedBall d R δ θ_star x))
